using System;
using System.Linq;
using System.Collections.ObjectModel;

// Focused reference snippets and separate complete crafting examples. Canonical aliases/signatures come from the language registry.
public static class BlueprintGuide
{
    public const string IntroductionTitle="대장간에 오신 것을 환영합니다!";
    public const string Introduction="도면을 보고 나만의 무기를 만들어보세요. 단, 도면은 숫자로 된 언어입니다!\n\n여러분은 도면에 명령을 적어 대장장이를 움직입니다. 재료를 올리고, 불에 달구고, 망치로 두드리고, 식히면서 하나의 무기를 완성해보세요. 어떤 재료와 공정을 선택하느냐에 따라 결과가 달라집니다.\n\n처음이라면 왼쪽 ‘시작’ 책갈피에서 ‘첫 검날 만들기’를 펼쳐보세요. 예제를 코드 창에 옮기고 한 줄씩 실행하며 숫자가 어떤 동작으로 이어지는지 살펴볼 수 있습니다. 재료와 함수가 궁금할 때는 이 안내서의 책갈피를 찾아보세요.\n\n이 게임의 도면 언어는 Python의 문법을 참고했습니다. 변수에 값을 저장하고, 들여쓰기로 명령을 묶습니다. 지원하는 숫자·기호 문법과 함수는 안내서에서 확인할 수 있습니다.\n\n작은 철 조각에서 시작해, 여러분만의 도면과 무기를 만들어가세요!";
    public sealed class Entry
    {
        public readonly string Id,Section,Title,Body,Example,Expected,Note;
        public readonly BlueprintFeature Feature;
        readonly string numericTitle,numericBody,numericExample,numericNote;
        public bool IsFunctionReference => Alias!=null&&Alias.Syntax==BlueprintSyntaxKind.Builtin||Id=="1"||Id=="2"||Id=="3"||Id=="4"||Id=="finish";
        public BlueprintAlias Alias => BlueprintAliases.Find(Feature);
        public string Heading => Alias==null?Title:(Alias.Symbol.Length==0?Alias.English:Alias.Symbol+" / "+Alias.English)+" · "+Title;
        public string Description => (Alias==null?"":Alias.Description+"\n"+Alias.Signature+"\n\n")+Body;
        public Entry(string id,string section,string title,string body,string example,string expected,string note,BlueprintFeature feature,string numericTitle=null,string numericBody=null,string numericExample=null,string numericNote=null)
        {this.numericTitle=numericTitle??title;this.numericBody=numericBody??body;this.numericExample=numericExample??example;this.numericNote=numericNote??note;Id=id;Section=section;Title=title;Body=body;Example=example;Expected=expected;Note=note;Feature=feature;}
        public string HeadingFor(bool englishUnlocked) => englishUnlocked?Heading:(Alias==null?numericTitle:(Alias.Symbol.Length==0?Alias.English:Alias.Symbol)+" · "+numericTitle);
        public string DescriptionFor(bool englishUnlocked) => englishUnlocked?Description:(Alias==null?"":Alias.Description+"\n"+Alias.Signature+"\n\n")+numericBody;
        public string ExampleFor(bool englishUnlocked) => englishUnlocked?Example:numericExample;
        public string NoteFor(bool englishUnlocked) => englishUnlocked?Note:numericNote;
        public bool Matches(string query,bool englishUnlocked)
        {return string.IsNullOrWhiteSpace(query)||(Section+" "+HeadingFor(englishUnlocked)+" "+DescriptionFor(englishUnlocked)).IndexOf(query.Trim(),StringComparison.OrdinalIgnoreCase)>=0;}
        public bool Matches(string query)
        {return string.IsNullOrWhiteSpace(query)||(Section+" "+Heading+" "+Description).IndexOf(query.Trim(),StringComparison.OrdinalIgnoreCase)>=0;}
    }
    public static readonly ReadOnlyCollection<Entry> Entries=Array.AsReadOnly(new[]{
        new Entry("start","시작하기","첫 검날 만들기","도면은 위에서 아래로 실행됩니다. 재료를 올리고, 가열하고, 타격한 다음 냉각하세요. !로 현재 결과물을 제출하고 평가받습니다. ! 없이도 공정과 계산을 실행할 수 있습니다.\n▷는 한 줄 실행입니다. 누를 때마다 다음 실행 줄을 처리하고 멈추며 변수와 작업물 상태를 유지합니다. ▶는 전체 실행 또는 멈춘 지점부터 계속 실행, ■는 중단입니다. 두 실행 모두 실제 재료를 소비합니다. 파란 줄이 다음 실행 위치입니다.","Material = 1\nBlade = 1(Material)\n2(Blade, 7)\n3(Blade)\n4(Blade, 0)\n!Blade","철 1개 · 제작비 0G · 판매가 28G · 순이익 28G","예제를 복사해 코드 창에 붙여 넣으세요. 실제 제작에는 철 1개가 필요하며 골드는 소비하지 않습니다.",BlueprintFeature.None),
        new Entry("variables","시작하기","변수 · 대입 · 들여쓰기","이름 = 값으로 값을 저장합니다. 이름은 문자 또는 _로 시작하며 대소문자를 구분합니다. 한글 이름도 가능합니다.\n블록은 : 뒤에서 시작하며 공백 4칸씩 들여씁니다. Enter는 자동 들여쓰기, Tab/Shift+Tab은 들여쓰기 조절입니다.\nif와 반복문 안에서 대입한 값은 같은 실행 범위에 남습니다. 실제로 값을 읽기 전에는 대입해야 합니다.","if True:\n    인사 = \"안녕하세요\"\nprint(인사)","디버그 창에 안녕하세요 출력","실행하지 않은 분기에서만 값을 대입했다면 변수 읽기 줄에서 오류가 납니다. 함수의 지역 변수는 호출 밖으로 나오지 않습니다.",BlueprintFeature.None,numericBody:"이름 = 값으로 값을 저장합니다. 이름은 문자 또는 _로 시작하며 대소문자를 구분합니다. 한글 이름도 가능합니다.\n블록은 : 뒤에서 시작하며 공백 4칸씩 들여씁니다. Enter는 자동 들여쓰기, Tab/Shift+Tab은 들여쓰기 조절입니다.\n1?와 반복문 안에서 대입한 값은 같은 실행 범위에 남습니다. 실제로 값을 읽기 전에는 대입해야 합니다.",numericExample:"1?(True):\n    인사 = \"안녕하세요\"\nprint(인사)"),
        new Entry("notation","시작하기","영문과 숫자 표기","영문과 숫자·기호 표기는 같은 기능입니다. 한 도면에 섞어 써도 됩니다.\n100(Blade)는 열 조회 함수지만 Value = 100의 100은 숫자입니다. 000()은 min()의 정확한 숫자 표기입니다.\n# 뒤는 주석입니다. 따옴표 문자열 안의 기호는 실행되지 않습니다.\n함수 이름은 연노랑, 제어문은 보라, 재료는 분홍, 주석은 초록, 변수는 흰색입니다.","Value = 100\nDistance = 101(-3) # abs(-3)과 같음\nprint(\"01?와 !!도 문자열 안에서는 글자\")","Value는 100, Distance는 3. 따옴표 안의 문장 출력","",BlueprintFeature.None,numericTitle:"숫자와 기호 표기",numericBody:"숫자·기호는 쓰인 위치에 따라 명령이나 값을 뜻합니다.\n100(Blade)는 열 조회 함수지만 Value = 100의 100은 숫자입니다. 000()은 목록의 최솟값을 구합니다.\n# 뒤는 주석입니다. 따옴표 문자열 안의 기호는 실행되지 않습니다.\n함수 이름은 연노랑, 제어문은 보라, 재료는 분홍, 주석은 초록, 변수는 흰색입니다.",numericExample:"Value = 100\nDistance = 101(-3) # 절댓값은 3\nprint(\"01?와 !!도 문자열 안에서는 글자\")"),
        new Entry("1","대장간 공정","1() · 재료 올리기","사용법: 작업물 = 1(재료 번호)\n등록된 재료 번호 0~9를 받습니다. 0 공기, 1 철, 2 나무, 3 물, 4 석탄, 5 은, 6 마력 수정, 7 별철, 8 서리수, 9 용뼈입니다. 해당 재료 1개만 소비합니다. 공기는 재고를 소비하지 않습니다. 반환된 작업물은 재료 정보를 유지합니다. 1(1)만 호출하거나 다른 함수의 인자로 전달해도 실행됩니다.","Blade = 1(1)","철 검날 완성 · 제작비 0G","예: Wood = 1(2), Water = 1(3). 실제 실행에는 해금과 보유량이 필요합니다. 미등록 번호·잘못된 타입은 오류입니다. 현재 성형되어 식은 철 검날은 28G, 원재료와 나머지 미완성품은 0G입니다.",BlueprintFeature.None),
        new Entry("2","대장간 공정","2() · 가열","사용법: 2(작업물, 목표 열 단계)\n이미 만든 작업물을 넣으세요. 목표는 정수 1~9이며 골드는 소비하지 않습니다. None을 반환합니다.","2(Blade, 7)","철 검날 완성 · 제작비 0G","2(Blade, 10)은 범위 오류입니다. x = 2(Blade, 7)은 가열을 실행하고 x에 None을 저장합니다.",BlueprintFeature.None),
        new Entry("3","대장간 공정","3() · 타격","사용법: 3(작업물)\n작업물을 두드립니다. 열 단계 6 이상일 때 성형되며 비용은 0G입니다. None을 반환합니다.","3(Blade)","철 검날 완성 · 제작비 0G","열 5 이하에서도 타격 동작은 실행되지만 성형 효과는 없습니다. 성형하려면 먼저 2(Blade, 7)을 실행하세요.",BlueprintFeature.None),
        new Entry("4","대장간 공정","4() · 냉각","사용법: 4(작업물, 냉각 재료)\n작업물과 냉각에 사용할 재료 번호를 전달합니다. 냉각 방법은 두 번째 인자로 지정합니다. 공기(0), 물(3), 서리수(8)를 사용할 수 있습니다. 열을 0으로 내리며 물은 뜨거운 성형 검날에 경도 7을 부여합니다. 공기를 사용할 때 비용은 0G이며 None을 반환합니다.","4(Blade, 0)","철 검날 완성 · 제작비 0G","물·서리수는 각각 재료 1개를 소비합니다. 물은 열 6 이상에서 담금질, 서리수는 열 4와 차이 3 이하에서 문양을 부여합니다.",BlueprintFeature.None),
        new Entry("extension-5","대장간 공정","5() · 손잡이 제작","사용법: 5(Item, Material)\n성형하고 식힌 검날에 선택한 재료 1개로 손잡이를 만듭니다. 철(1), 나무(2), 은(5), 별철(7)을 사용할 수 있습니다. 기본 제공 함수이며 골드는 소비하지 않습니다. None을 반환합니다.\n기존 정제 용뼈·공명 수정 작업물 장착도 지원합니다.","p = 1(1)\n2(p, 7)\n3(p)\n4(p, 0)\n5(p, 2)\n!p","나무 손잡이가 있는 검 완성","손잡이 재료 1개가 필요합니다. 이미 손잡이가 있는 검에는 다시 만들 수 없습니다.",BlueprintFeature.Attach),
        new Entry("finish","대장간 공정","! · 완성품 판정","사용법: !작업물\n작업물 또는 등록된 재료 번호를 제출하고 도면을 끝냅니다. 식은 철 검날은 28G, 원재료·미완성품은 0G입니다. res = 1 다음 줄에 !res를 쓰면 철 1개를 그대로 제출합니다. 원재료 제출은 가공비 없이 해당 재고만 소비합니다. ! 없이도 실행할 수 있습니다.","!Blade","철 검날 완성 · 제작비 0G","!는 함수 호출이 아닙니다. 반복문·사용자 함수 안에서는 사용할 수 없습니다. ! 뒤에 명령을 더 쓰지 마세요.",BlueprintFeature.None),
        new Entry("if","조건과 반복","조건이 참일 때","사용법: 1?(조건): 또는 if 조건:\n조건이 True이면 들여쓴 블록을 실행합니다. 조건은 비교식 또는 True/False여야 합니다.","Heat = 7\n1?(Heat > 7):\n    print(\"너무 뜨겁습니다\")\n01?(Heat >= 6):\n    print(\"타격할 수 있습니다\")\n0?:\n    print(\"더 가열하세요\")","타격할 수 있습니다 출력","1?(1):처럼 정수를 조건으로 넣으면 오류입니다.",BlueprintFeature.If,numericBody:"사용법: 1?(조건):\n조건이 True이면 들여쓴 블록을 실행합니다. 조건은 비교식 또는 True/False여야 합니다."),
        new Entry("elif","조건과 반복","다음 조건 검사","사용법: 01?(조건): 또는 elif 조건:\n앞에서 선택된 분기가 없을 때 다음 조건을 검사합니다. 여러 개 연결할 수 있지만 첫 참 분기 하나만 실행합니다.","Heat = 7\n1?(Heat > 7):\n    print(\"너무 뜨겁습니다\")\n01?(Heat >= 6):\n    print(\"타격할 수 있습니다\")\n0?:\n    print(\"더 가열하세요\")","첫 번째 조건은 거짓, 두 번째 조건만 실행","if와 같은 들여쓰기에서 작성하세요. elif를 단독으로 쓰거나 else 뒤에 쓸 수 없습니다.",BlueprintFeature.Elif,numericBody:"사용법: 01?(조건):\n앞에서 선택된 분기가 없을 때 다음 조건을 검사합니다. 여러 개 연결할 수 있지만 첫 참 분기 하나만 실행합니다.",numericNote:"1?와 같은 들여쓰기에서 작성하세요. 01?를 단독으로 쓰거나 0? 뒤에 쓸 수 없습니다."),
        new Entry("else","조건과 반복","어느 조건도 맞지 않을 때","사용법: 0?: 또는 else:\n앞선 if/elif 조건이 모두 거짓이면 실행합니다. 조건이나 괄호를 넣지 않으며 마지막에 둡니다.","Heat = 4\n1?(Heat > 7):\n    print(\"너무 뜨겁습니다\")\n01?(Heat >= 6):\n    print(\"타격할 수 있습니다\")\n0?:\n    print(\"더 가열하세요\")","더 가열하세요 출력","else는 연결된 if가 있어야 합니다.",BlueprintFeature.Else,numericBody:"사용법: 0?:\n앞선 1?/01? 조건이 모두 거짓이면 실행합니다. 조건이나 괄호를 넣지 않으며 마지막에 둡니다.",numericNote:"0?는 연결된 1?가 있어야 합니다."),
        new Entry("while","조건과 반복","조건을 확인하며 반복","사용법: 888(조건): 또는 while 조건:\n각 회차 전에 조건을 확인합니다. 반복문 안에서 조건에 쓰는 값을 바꿔 언젠가 끝나도록 만드세요.","Count = 0\n888(Count < 3):\n    print(\"타격 준비\")\n    Count = Count + 1","타격 준비를 3번 출력","끝나지 않는 반복은 실행 한도에서 중단됩니다.",BlueprintFeature.While,numericBody:"사용법: 888(조건):\n각 회차 전에 조건을 확인합니다. 반복문 안에서 조건에 쓰는 값을 바꿔 언젠가 끝나도록 만드세요."),
        new Entry("for","조건과 반복","목록을 순서대로 순회","사용법: 123(이름 in 목록): 또는 for 이름 in 목록:\n정수 리스트 또는 튜플의 원소를 순서대로 변수에 넣고 본문을 실행합니다. 시작 시점의 목록을 순회합니다.","123(Heat in [9, 7, 5]):\n    1?(Heat <= 7):\n        print(\"7 이하 후보\")","7과 5에서 각각 출력하여 총 2번 출력","range()나 딕셔너리·집합 순회는 아직 지원하지 않습니다.",BlueprintFeature.For,numericBody:"사용법: 123(이름 in 목록):\n정수 리스트 또는 튜플의 원소를 순서대로 변수에 넣고 본문을 실행합니다. 시작 시점의 목록을 순회합니다.",numericNote:"범위 생성 함수나 딕셔너리·집합 순회는 아직 지원하지 않습니다."),
        new Entry("break","조건과 반복","반복을 즉시 끝내기","사용법: !! 또는 break\n가장 가까운 반복문 하나를 종료합니다. 바깥쪽 반복문이나 함수 전체를 끝내지는 않습니다.","123(Heat in [9, 7, 5]):\n    1?(Heat <= 7):\n        print(\"첫 적합값 발견\")\n        !!","후보 7에서 한 번 출력하고 반복 종료","반복문 밖에서 사용하면 오류입니다. !Blade(완성품 판정)와 다릅니다.",BlueprintFeature.Break,numericBody:"사용법: !!\n가장 가까운 반복문 하나를 종료합니다. 바깥쪽 반복문이나 함수 전체를 끝내지는 않습니다."),
        new Entry("continue","조건과 반복","다음 회차로 건너뛰기","사용법: ~~ 또는 continue\n현재 회차의 남은 명령을 건너뛰고 가장 가까운 반복문의 다음 회차로 갑니다.","123(Heat in [9, 7, 5]):\n    1?(Heat > 7):\n        ~~\n    print(\"사용할 수 있는 후보\")","9는 건너뛰고 나머지 두 회차에서 출력","while에서는 continue 전에 카운터를 바꾸지 않으면 같은 회차 조건이 계속 반복될 수 있습니다.",BlueprintFeature.Continue,numericBody:"사용법: ~~\n현재 회차의 남은 명령을 건너뛰고 가장 가까운 반복문의 다음 회차로 갑니다.",numericNote:"888에서는 ~~ 전에 카운터를 바꾸지 않으면 같은 회차 조건이 계속 반복될 수 있습니다."),
        new Entry("def","사용자 함수","내 함수 만들기","사용법: 333 함수명(매개변수): 또는 def 함수명(매개변수):\n정의만으로는 본문이 실행되지 않습니다. 함수명(값)으로 호출합니다. 최대 8개 매개변수를 받을 수 있습니다.\n필요한 값은 인자로 전달하세요. 함수 안의 변수는 해당 호출에서만 사용합니다.","333 message(ready):\n    1?(ready):\n        << \"준비 완료\"\n    << \"대기 중\"\nprint(message(True))","message(True)가 준비 완료를 반환해 출력","함수는 도면 최상위에서 정의합니다. 직접·상호 재귀를 지원합니다. 종료 조건을 넣으세요. 동시 호출 깊이는 32단계입니다. 333: 문법은 사용하지 않습니다.",BlueprintFeature.Def,numericBody:"사용법: 333 함수명(매개변수):\n정의만으로는 본문이 실행되지 않습니다. 함수명(값)으로 호출합니다. 최대 8개 매개변수를 받을 수 있습니다.\n필요한 값은 인자로 전달하세요. 함수 안의 변수는 해당 호출에서만 사용합니다."),
        new Entry("recursion","사용자 함수","재귀 · 함수를 다시 호출하기","함수가 자기 자신을 호출하거나 다른 함수와 서로 호출할 수 있습니다. 각 호출의 매개변수·지역 변수는 독립적이며, 반환하면 이전 호출로 돌아갑니다.\n반드시 종료 조건을 넣으세요. import로 가져온 함수도 재귀를 사용할 수 있고, 재귀 속 공정도 순서대로 실행됩니다.","333 factorial(n):\n    1?(n <= 1):\n        << 1\n    << n * factorial(n - 1)\nprint(factorial(5))","120 출력","동시에 열린 함수 호출은 최대 32단계, 전체 실행은 10000명령입니다. 한도를 넘으면 실행 오류로 중단하며 이미 성공한 공정의 비용은 유지합니다. 모듈 초기화 중 서로 가져오는 순환 import 제한은 별도입니다.",BlueprintFeature.None),
        new Entry("import","사용자 함수","import · 다른 코드창 가져오기","코드창 제목이 모듈 이름입니다. 제목을 smith처럼 문자 또는 _로 시작하는 공백 없는 이름으로 지정하세요. 한글 이름도 가능합니다.\nimport smith 후 smith.forge(1)로 호출합니다. import smith as s 후 s.forge(1)도 같습니다.\nfrom smith import forge 또는 from smith import forge as make로 함수를 직접 가져옵니다. 쉼표로 여러 이름을 지정할 수 있고 from smith import *는 _로 시작하지 않는 이름을 가져옵니다.\n가져온 창의 최상위 코드는 한 실행에서 처음 가져올 때 한 번 실행됩니다. 함수는 자신이 정의된 모듈의 변수와 함수를 읽습니다. 비용·재고·대장장이 동작은 호출한 실행에 합산됩니다.","import smith as s\nBlade = s.forge(1)\n!Blade","smith 창의 제작 함수 실행 · 철 1개 · 제작비 0G · 판매가 28G","먼저 다른 코드창의 제목을 smith로 바꾸고 아래 함수를 작성하세요.\n333 forge(material):\n    blade = 1(material)\n    2(blade, 7)\n    3(blade)\n    4(blade, 0)\n    << blade\n\n창 제목이 중복되면 가져올 수 없습니다. 순환 import·외부 Python 패키지·상대 경로는 지원하지 않습니다. ! 제출은 호출한 실행 창에서 하세요. 모듈을 수정한 내용은 다음 실행부터 적용됩니다.",BlueprintFeature.None),
        new Entry("return","사용자 함수","함수 결과 돌려주기","사용법: << 값 또는 return 값\n현재 함수를 즉시 끝내고 값을 호출한 곳으로 돌려줍니다. 함수 안의 반복문 속에서도 함수를 끝냅니다.\n값을 생략하거나 return 없이 끝나면 None입니다.","333 message(ready):\n    1?(ready):\n        << \"준비 완료\"\n    << \"대기 중\"\nprint(message(True))","준비 완료 출력","함수 밖에서 사용할 수 없습니다. <<는 !완성품 판정과 다릅니다.",BlueprintFeature.Return,numericBody:"사용법: << 값\n현재 함수를 즉시 끝내고 값을 호출한 곳으로 돌려줍니다. 함수 안의 반복문 속에서도 함수를 끝냅니다.\n값을 생략하거나 << 없이 끝나면 None입니다."),
        new Entry("heat","조회와 계산","작업물의 열 읽기","사용법: 100(작업물) 또는 heat(작업물)\n이미 만든 작업물의 현재 열 단계 0~9를 정수로 반환합니다. 작업물과 비용은 바뀌지 않습니다.","Heat = 100(Blade)","열 7을 읽고 타격 준비 완료 출력 후 완성","숫자 1 자체는 작업물이 아닙니다. 먼저 Blade = 1(1)로 만든 작업물을 넣으세요.",BlueprintFeature.Heat,numericBody:"사용법: 100(작업물)\n이미 만든 작업물의 현재 열 단계 0~9를 정수로 반환합니다. 작업물과 비용은 바뀌지 않습니다."),
        new Entry("abs","조회와 계산","절댓값","사용법: 101(정수) 또는 abs(정수)\n음수의 부호를 없앤 크기를 반환합니다. 재료의 열을 바꾸는 기능은 아닙니다.","Distance = 101(-3) # 3","절댓값은 3 출력","정수 범위를 넘는 결과는 오류입니다.",BlueprintFeature.Abs,numericBody:"사용법: 101(정수)\n음수의 부호를 없앤 크기를 반환합니다. 재료의 열을 바꾸는 기능은 아닙니다."),
        new Entry("len","조회와 계산","원소 수 세기","사용법: 1111(컬렉션) 또는 len(컬렉션)\n리스트·튜플·집합·딕셔너리의 원소 수를 반환합니다. 빈 대상은 0입니다.","Count = 1111([9, 7, 5]) # 3","후보는 3개 출력","현재 len(\"문자열\")은 지원하지 않습니다.",BlueprintFeature.Len,numericBody:"사용법: 1111(컬렉션)\n리스트·튜플·집합·딕셔너리의 원소 수를 반환합니다. 빈 대상은 0입니다.",numericNote:"현재 1111(\"문자열\")은 지원하지 않습니다."),
        new Entry("min","조회와 계산","최솟값","사용법: 000(목록) 또는 min(목록)\n정수 리스트 또는 튜플에서 가장 작은 값을 반환합니다.","Target = 000([9, 7, 5]) # 5","Target은 5, 값 찾기 메시지 출력","빈 목록, 딕셔너리, 집합은 인자로 사용할 수 없습니다.",BlueprintFeature.Min,numericBody:"사용법: 000(목록)\n정수 리스트 또는 튜플에서 가장 작은 값을 반환합니다."),
        new Entry("max","조회와 계산","최댓값","사용법: 999(목록) 또는 max(목록)\n정수 리스트 또는 튜플에서 가장 큰 값을 반환합니다.","Target = 999([9, 7, 5]) # 9","Target은 9, 값 찾기 메시지 출력","빈 목록, 딕셔너리, 집합은 인자로 사용할 수 없습니다.",BlueprintFeature.Max,numericBody:"사용법: 999(목록)\n정수 리스트 또는 튜플에서 가장 큰 값을 반환합니다."),
        new Entry("random","조회와 계산","무작위 정수","사용법: 66(최솟값, 최댓값) 또는 random(최솟값, 최댓값)\n두 경계를 모두 포함한 정수 하나를 돌려줍니다. 66(1, 7)은 1과 7도 나올 수 있습니다.","Roll = 66(1, 7) # 1~7 중 하나","범위 안의 정수 선택 후 메시지 출력","인자는 반드시 두 개이고 최솟값 ≤ 최댓값이어야 합니다. 한 줄 실행과 전체 실행은 같은 시작 상태에서 같은 난수 순서를 사용합니다. 멈췄다가 이어 실행해도 난수를 다시 뽑지 않습니다.",BlueprintFeature.Random,numericBody:"사용법: 66(최솟값, 최댓값)\n두 경계를 모두 포함한 정수 하나를 돌려줍니다. 66(1, 7)은 1과 7도 나올 수 있습니다."),
        new Entry("set","자료 묶음","빈 집합 만들기","사용법: 1010() 또는 set()\n중복 원소가 없는 빈 정수 집합을 돌려줍니다. 원소를 지정할 때는 {0, 1}처럼 작성합니다.","Empty = 1010()","빈 집합입니다 출력","set([1, 2])는 지원하지 않습니다. {}는 빈 집합이 아닌 빈 딕셔너리입니다.",BlueprintFeature.Set,numericBody:"사용법: 1010()\n중복 원소가 없는 빈 정수 집합을 돌려줍니다. 원소를 지정할 때는 {0, 1}처럼 작성합니다.",numericNote:"1010([1, 2])는 지원하지 않습니다. {}는 빈 집합이 아닌 빈 딕셔너리입니다."),
        new Entry("print","출력","여러 값과 변수 출력","사용법: print(값, ...)\n문자열뿐 아니라 정수, True/False, None, 변수, 계산 결과, 컬렉션과 작업물을 출력합니다.\n여러 인자는 쉼표로 나누어 전달하며, 출력에서는 공백으로 구분됩니다. print()는 빈 줄을 출력합니다.\n리스트는 [1, 2], 튜플은 (1, 2), 집합은 {1, 2}, 딕셔너리는 {1: 2} 형태로 표시됩니다. print(Blade)는 작업물의 열·성형 여부·특성을 보여줍니다.\n비용은 0G이며 None을 반환합니다. 출력 전용 코드는 ! 없이 실행할 수 있습니다. 실제로 실행된 메시지만 순서대로 표시합니다.","value = 7\nprint(\"안녕하세요\")\nprint(\"현재 값:\", value, \"계산:\", value + 3)\nprint(True, False, None)\nprint([1, 2, 3], (4, 5), {6: 7})\nprint()","안녕하세요\n현재 값: 7 계산: 10\nTrue False None\n[1, 2, 3] (4, 5) {6: 7}\n(마지막에 빈 줄 출력)","지원하는 도면 언어 값에 한해 출력합니다. 컬렉션 원소는 정수만 지원합니다. sep/end 키워드 인자, f문자열은 아직 지원하지 않습니다. 실행당 최대 256회/65536자입니다.",BlueprintFeature.Print),
        new Entry("list","자료 묶음","리스트 · 순서 있는 목록","[9, 7, 5]처럼 정수를 순서대로 담습니다. 인덱스는 0부터 시작하며 변수[인덱스]로 읽거나 바꿀 수 있습니다.\n목록을 다른 변수에 대입하면 복사됩니다.","Values = [9, 7, 5]\nValues[0] = 7\n1?(Values[0] == 7):\n    print(\"첫 후보를 바꿨습니다\")","첫 후보를 바꿨습니다 출력","음수/범위 밖 인덱스는 오류입니다. 301(목록,값)으로 추가하고 302(목록)으로 마지막 원소를 꺼냅니다.",BlueprintFeature.None,numericNote:"음수/범위 밖 인덱스는 오류입니다. 301(목록,값)으로 추가하고 302(목록)으로 마지막 원소를 꺼냅니다."),
        new Entry("dict","자료 묶음","딕셔너리 · 번호별 수량","{1: 3}은 번호 1에 수량 3을 연결합니다. 정수 키와 정수 값만 담을 수 있습니다.\n없는 키에 대입하면 새 항목을 만들고, 같은 키에 다시 대입하면 값을 바꿉니다.","Stock = {1: 3}\nStock[1] = Stock[1] - 1\n1?(Stock[1] == 2):\n    print(\"기록한 수량은 2\")","기록한 수량은 2 출력","없는 키를 읽으면 그 줄에서 오류입니다. 이 목록은 플레이어의 계산용 기록이며 실제 철 재고를 바꾸지 않습니다.",BlueprintFeature.None),
        new Entry("tuple","자료 묶음","튜플 · 고정된 묶음","(6, 7)처럼 변경하지 않을 정수 묶음을 만듭니다. 인덱스로 읽고, for로 순회하고, min/max/len에 넣을 수 있습니다.","Bounds = (6, 7)\n1?(000(Bounds) == 6):\n    print(\"최저 기준은 6\")","최저 기준은 6 출력","Bounds[0] = 5처럼 바꿀 수 없습니다. 원소 하나짜리는 (6,)이고 빈 튜플은 ()입니다.",BlueprintFeature.None,numericBody:"(6, 7)처럼 변경하지 않을 정수 묶음을 만듭니다. 인덱스로 읽고, 123로 순회하고, 000/999/1111에 넣을 수 있습니다."),
        new Entry("membership","자료 묶음","집합과 포함 여부 in","{0, 0, 1}은 중복 0을 하나로 합쳐 {0, 1}이 됩니다. 값 in 대상은 포함 여부를 True/False로 반환합니다.\n리스트·튜플·집합에서는 원소, 딕셔너리에서는 키를 확인합니다.","Allowed = {0, 0, 1}\n1?(0 in Allowed):\n    print(\"공기 냉각 허용\")","공기 냉각 허용 출력","현재 컬렉션에는 정수만 넣을 수 있으며 한 컬렉션은 최대 1024개입니다.",BlueprintFeature.None),
        new Entry("operators","기본 문법","계산 · 비교 · 논리","계산: + 더하기, - 빼기/음수, * 곱하기, // 몫, % 나머지\n비교: == 같음, != 다름, < 작음, <= 이하, > 큼, >= 이상\n논리: and 둘 다 참, or 하나 이상 참, not 반대로\nTrue는 참, False는 거짓, None은 값 없음입니다.","Heat = 7\nReady = Heat >= 6 and Heat <= 7\n1?(Ready):\n    print(\"타격 가능한 열\")","타격 가능한 열 출력","6 <= Heat <= 7 대신 and로 연결하세요. / 나누기·소수는 없습니다. 0으로 나누거나 정수 범위를 넘으면 오류입니다.",BlueprintFeature.None),
        new Entry("stages","완성 예제","반복으로 공정 순서 만들기","a를 1부터 늘리며 한 회차에 한 공정을 선택합니다. 첫 회차에서 만든 res를 다음 회차와 반복문 밖에서도 사용합니다.","a = 1\n888(True):\n    1? a == 1:\n        res = 1(a)\n    01? a == 2:\n        2(res, 7)\n    01? a == 3:\n        3(res)\n    01? a == 4:\n        4(res, 0)\n    01? a == 5:\n        !!\n    a = a + 1\n!res","철 1개 · 제작비 0G · 완성품 생성","a가 5가 되면 !!로 반복을 끝내고, 바깥의 !res로 완성품을 판정합니다.",BlueprintFeature.None),
        new Entry("choose","완성 예제","첫 적합 열 찾기","사용자 함수가 [9, 7, 5]를 검사해 제한 7 이하인 첫 후보를 반환합니다. !!로 탐색을 끝내고 가열은 한 번만 합니다.","333 choose(values, limit):\n    selected = None\n    123(candidate in values):\n        1?(candidate <= limit):\n            selected = candidate\n            !!\n    << selected\nTarget = choose([9, 7, 5], 7)\n1?(Target != None):\n    Blade = 1(1)\n    2(Blade, Target)\n    3(Blade)\n    4(Blade, 0)\n    !Blade\n0?:\n    print(\"맞는 열 단계가 없습니다\")","후보 7 선택 · 가열 1회 · 제작비 0G","목록을 [9, 8]로 바꾸면 공정과 비용 없이 안내 메시지만 출력합니다.",BlueprintFeature.None),
        new Entry("errors","문제가 생겼을 때","오류와 비용 확인","▷로 시작하면 앞부분부터 실행하고 문법·함수 이름·인자 수 오류는 해당 줄에 도달했을 때 표시합니다. 새로 ▶로 시작할 때는 전체 문법 검사를 먼저 합니다.\n변수의 값과 현재 타입, 공정 상태는 실제 실행 시점에 확인합니다. 함수·분기 안의 오류도 실행 경로가 도달했을 때 중단합니다. 괄호·따옴표·들여쓰기 오류는 안전하게 해석 가능한 앞부분까지만 진행합니다. 오류 줄 이후는 실행하지 않습니다.\n실제 제작에서 이미 소비한 재료는 돌아오지 않습니다. ▷로 한 줄씩 확인할 수 있지만 실제 재료가 소비됩니다. 아직 실행하지 않은 줄의 공정과 출력은 발생하지 않습니다.\n실행 명령 10000, 함수 호출 깊이 32입니다. 재귀도 같은 한도를 공유합니다.","Material = 1\nBlade = 1(Material)\n2(Blade, 7)\n3(Blade)\n4(Blade, 0)\n!Blade","정상 기본 도면: 제작비 0G · 판매가 28G","가열을 한 번 더 해도 같은 상태의 검날 판매가는 28G입니다. 추가 가열에도 골드는 소비되지 않습니다.",BlueprintFeature.None)
    }.Concat(ForgeExpansion.Definitions.Where(d=>d.Alias.Id!=BlueprintFeature.Attach).Select(d=>new Entry("extension-"+d.Alias.Symbol,(d.Alias.Id==BlueprintFeature.Lucky||d.Alias.Id==BlueprintFeature.LuckyCode)?"조회와 계산":"확장 제작",d.Alias.Symbol+"()",d.Alias.Description,d.Example,"함수 설명에 따라 공정·반환값이 적용됩니다.",d.Alias.Id==BlueprintFeature.Speed?"스피드 1~5단계를 순서대로 구매합니다. 단계별 100/150/200/300/450G, 구매한 단계까지만 설정할 수 있습니다.":d.Alias.Id==BlueprintFeature.AutoSell?"스피드 5단계까지 모두 구매하면 추가 비용 없이 해금되어 자동판매가 켜집니다.":d.Price>0?"테크 트리에서 "+ForgeTechnology.Find("function-"+d.Alias.Id).Price+"G로 해금합니다. "+(d.Alias.Id==BlueprintFeature.Lucky||d.Alias.Id==BlueprintFeature.LuckyCode?"777()와 778()이 함께 해금됩니다. ":"")+"필요한 재료도 구매하세요.":"기본 제공 함수입니다. 공정에 필요한 재료는 별도로 보유해야 합니다.",d.Alias.Id))).Concat(new[]{
        new Entry("is-day","시간 조회","12() · 낮인지 확인","정오의 12에서 연상합니다. 06:00 이상 18:00 미만이면 정수 1, 나머지 시간에는 0입니다. 호출 순간의 게임 시각을 읽으며 자원은 소비하지 않습니다.","Daylight = 12()\nprint(Daylight)\n1? Daylight == 1:\n    print(\"낮입니다\")","오전 8시 예: 1과 낮입니다 출력","시간 조회 묶음(12 + 24)을 40G로 함께 해금합니다. 반환값은 bool이 아닌 정수이므로 조건에는 12() == 1처럼 비교하세요.",BlueprintFeature.IsDay),
        new Entry("night-time","시간 조회","24() · 밤인지 확인","자정의 24에서 연상합니다. 18:00 이상 또는 06:00 미만이면 정수 1, 낮이면 0입니다. 24(60) 시각 조회도 함께 해금됩니다.","Night = 24()\nprint(Night)\n1? Night == 1:\n    print(\"밤입니다\")","오전 8시 예: 0 출력","시간 조회 묶음(12 + 24)을 40G로 함께 해금합니다. 조건에는 24() == 1처럼 비교하세요. 호출 비용은 0G입니다.",BlueprintFeature.NightTime),
        new Entry("clock-minutes","시간 조회","24(60) · 현재 시각 조회","하루 24시간과 한 시간 60분을 연결합니다. 자정부터 지난 분을 0~1439의 정수로 반환하며 초는 버립니다. 24:00에는 0으로 돌아갑니다. 한 줄 실행에서도 각 호출 시점의 시각을 읽습니다.","Minutes = 24(60)\nHour = Minutes // 60\nMinute = Minutes % 60\nprint(Hour, Minute)","오전 8시 예: 8 0 출력","24() 해금에 포함됩니다. 인자는 정수 60만 허용합니다. 현실 시간이 아닌 게임 속 시각이며 기본 하루는 현실 10분입니다. 호출 비용과 재료 소비는 없습니다.",BlueprintFeature.None),
    }).Concat(ForgeSmithLanguage.Aliases.Select(a=>new Entry("extension-smith-"+a.Symbol,"대장장이와 다이아몬드",a.Symbol+"()",a.Description+"\n"+a.Signature,ForgeSmithLanguage.Example(a.Id),a.Id==BlueprintFeature.SmithRun?"고용한 대장장이 1번이 독립 실행하고 반환한 검을 제출합니다.":"공방의 해당 대장장이 상태를 조회하거나 변경합니다.","대장장이 번호는 0부터 시작합니다. 첫 위치는 (0,0)입니다. 대장장이 함수는 코드창에서 연파랑으로 표시합니다. 조회 연구와 고용은 대장장이 테크 트리에서 다이아로 구매합니다. 예제 실행 전 필요한 고용·연구·재료를 준비하세요.",a.Id))).ToArray());
